<template>
  <el-select
    :model-value="modelValue"
    @update:model-value="handleChange"
    :placeholder="placeholder"
    class="ai-media-model-selector"
    popper-class="ai-media-model-popper"
    :teleported="false"
    :offset="0"
  >
          <el-option
        v-for="option in options"
        :key="option.value"
        :label="option.label"
        :value="option.value"
        :disabled="option.disabled"
        class="ai-media-model-option-item"
        :class="{ 'has-description': showDescription && option.description }"
        
      >
      <div class="ai-media-model-option">
        <!-- 条件显示圆形单选按钮 -->
        <div v-if="showRadio" class="option-indicator">
          <div 
            class="radio-circle" 
            :class="{ 'selected': modelValue === option.value }"
          >
            <div v-if="modelValue === option.value" class="radio-dot"></div>
          </div>
        </div>
        <div class="option-content" :class="{ 'no-radio': !showRadio }">
          <div class="model-name">{{ option.label }}</div>
          <!-- 条件显示描述文字 -->
          <div v-if="showDescription && option.description" class="model-description">
            {{ option.description }}
          </div>
        </div>
      </div>
    </el-option>
  </el-select>
</template>

<script setup>
import { useChatModelStore } from '@/store/modules/chat-model';
import { ref, onMounted, watch } from 'vue';

const chatModelStore = useChatModelStore();
const props = defineProps({
  modelValue: {
    type: String,
    default: ''
  },
  type: {
    type: String,
    default: 'media'
  },
  placeholder: {
    type: String,
    default: 'Please select'
  },
  showRadio: {
    type: Boolean,
    default: true
  },
  showDescription: {
    type: Boolean,
    default: true
  }
});

// 使用响应式数据存储选项
const options = ref([]);

// 加载选项数据
const loadOptions = async () => {
  if (props.type === 'media') {
    try {
      const mediaModels = await chatModelStore.getMediaModels();
      options.value = mediaModels;
    } catch (error) {
      console.error('Failed to load media models:', error);
      options.value = [];
    }
  } else if (props.type === 'video') {
    try {
      const videoModels = await chatModelStore.getVideoMediaModels();
      options.value = videoModels;
    } catch (error) {
      console.error('Failed to load video models:', error);
      options.value = [];
    }
  } else {
    options.value = [];
  }
};

// 监听 type 变化，重新加载选项
watch(() => props.type, () => {
  loadOptions();
}, { immediate: false });

// 组件挂载时加载选项
onMounted(() => {
  loadOptions();
});

const emit = defineEmits(['update:modelValue']);

const handleChange = (value) => {
  emit('update:modelValue', value);
};
</script>

